 [['Pada data2,3,2,4,2, frekuensi nilai2 adalah ...',['2','3','4','5'],1,'Nilai2 muncul tiga kali dalam daftar.'],['Jumlah frekuensi seluruh kategori menunjukkan ...',['banyak data','selalu nilai terbesar','selalu panjang benda','nama pemilik'],0,'Setiap data dihitung sekali sehingga total frekuensi sama dengan jumlah data.']]],
